import heapq

def solve(grid, start, goal):
    if 0 <= start[0] < len(grid) and 0 <= start[1] < len(grid[0]) and (grid[start[0]][start[1]] == '#'):
        return []
    if 0 <= goal[0] < len(grid) and 0 <= goal[1] < len(grid[0]) and (grid[goal[0]][goal[1]] == '#'):
        return []
    if start == goal:
        return [start]
    rows, cols = (len(grid), len(grid[0]))
    visited = set()
    heap = [(0, 0, start)]
    parent = {}
    counter = 1
    while heap:
        steps, _, cell = heapq.heappop(heap)
        if cell in visited:
            continue
        if cell == goal:
            break
        visited.add(cell)
        r, c = cell
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = (r + dr, c + dc)
            if 0 <= nr < rows and 0 <= nc < cols and (grid[nr][nc] == '.') and ((nr, nc) not in visited):
                parent[nr, nc] = cell
                heapq.heappush(heap, (steps + 1, counter, (nr, nc)))
                counter += 1
    if goal not in parent:
        return []
    path = []
    curr = goal
    while curr != start:
        path.append(curr)
        curr = parent[curr]
    path.append(start)
    return path[::-1]

